import { daysBetween } from './dates.js';
import { balanceDue } from './payments.js';
import { lineTotal, lineDiscount, lineVat } from './invoices.js';

/**
 * Get invoices that are overdue (due date before asOf).
 * @param {Array} invoices - all invoices to filter from
 * @param {string} asOf - cutoff date in YYYY-MM-DD format
 * @returns {Array} overdue invoices sorted by most overdue first
 */
export function overdueInvoices(invoices, asOf) {
  return invoices
    .filter((inv) => inv.status === 'issued' || inv.status === 'partially_paid')
    .filter((inv) => inv.dueDate && inv.dueDate < asOf)
    .map((inv) => ({
      number: inv.number,
      customerId: inv.customerId,
      dueDate: inv.dueDate,
      daysOverdue: daysBetween(inv.dueDate, asOf),
      due: balanceDue(inv),
    }))
    .sort((a, b) => b.daysOverdue - a.daysOverdue);
}

/**
 * Get a summary of VAT by rate across invoices.
 * @param {Array} invoices - all invoices to summarize
 * @returns {Array} VAT summary entries sorted by rate high to low
 */
export function vatSummary(invoices) {
  const vatMap = {};

  for (const inv of invoices) {
    if (inv.status !== 'issued' && inv.status !== 'partially_paid' && inv.status !== 'paid') {
      continue;
    }

    for (const line of inv.lines) {
      const rate = line.vatRate ?? 0;
      const base = lineTotal(line) - lineDiscount(line);
      const vat = lineVat(line);

      if (!vatMap[rate]) {
        vatMap[rate] = { rate, base: 0, vat: 0 };
      }
      vatMap[rate].base += base;
      vatMap[rate].vat += vat;
    }
  }

  return Object.values(vatMap).sort((a, b) => b.rate - a.rate);
}

/**
 * Calculate late fee for an overdue invoice.
 * Late fee is 0.04% of amount due per day overdue.
 * @param {{ status: string, dueDate?: string }} invoice
 * @param {string} asOf - cutoff date in YYYY-MM-DD format
 * @returns {number} late fee in cents, 0 if not overdue or paid
 */
export function lateFee(invoice, asOf) {
  if (invoice.status === 'paid' || !invoice.dueDate) {
    return 0;
  }

  if (invoice.dueDate >= asOf) {
    return 0;
  }

  const daysOverdue = daysBetween(invoice.dueDate, asOf);
  const due = balanceDue(invoice);
  const fee = due * daysOverdue * 0.0004;
  return Math.round(fee);
}

